import PokemonData from "./PokemonData";
import skillList from "../Skill/skillList";
import { itemText } from "../Item";
import { abilObject } from "../Ability";
import { getMegaData } from "./MegaData";
//배틀용 포켓몬 객체
//원본(PokemonData)에서 노력치, 스킬, 지닌 도구를 설정한다
//ReadOnly, 불변값으로 Pokemon 객체가 origin으로 지니고있는다
export function parseEvs(evs) {
  if (Array.isArray(evs)) {
    return {
      hp: evs[0] ?? 0,
      atk: evs[1] ?? 0,
      def: evs[2] ?? 0,
      catk: evs[3] ?? 0,
      cdef: evs[4] ?? 0,
      speed: evs[5] ?? 0,
    };
  }

  if (typeof evs === "string") {
    const statKeyMap = {
      H: "hp",
      A: "atk",
      B: "def",
      C: "catk",
      D: "cdef",
      S: "speed",
    };
    const cleanStr = evs.trim().toUpperCase();

    // 패턴 1: "HA252", "CS252", "HB252", "AS252", "HD252", "HC252", "BD252" 등 또는 세부 4스탯 포함 형태 ("HA252S4" 등)
    const match252 = cleanStr.match(/^([HABCDS]{2})252(?:\s*([HABCDS])(\d+))?$/);
    if (match252) {
      const s1 = match252[1][0];
      const s2 = match252[1][1];
      const result = { hp: 0, atk: 0, def: 0, catk: 0, cdef: 0, speed: 0 };
      result[statKeyMap[s1]] = 252;
      result[statKeyMap[s2]] = 252;

      let extraStat = match252[2];
      let extraVal = match252[3] ? parseInt(match252[3], 10) : 4;

      if (!extraStat) {
        if (![s1, s2].includes("H")) extraStat = "H";
        else if (![s1, s2].includes("B")) extraStat = "B";
        else extraStat = "D";
      }
      result[statKeyMap[extraStat]] = (result[statKeyMap[extraStat]] || 0) + extraVal;
      return result;
    }

    // 패턴 2: "H252A252B4", "H252 A252 B4" 등 개별 지정
    const individualMatches = [...cleanStr.matchAll(/([HABCDS])(\d+)/g)];
    if (individualMatches.length > 0) {
      const result = { hp: 0, atk: 0, def: 0, catk: 0, cdef: 0, speed: 0 };
      for (const m of individualMatches) {
        const key = statKeyMap[m[1]];
        if (key) {
          result[key] = parseInt(m[2], 10);
        }
      }
      return result;
    }
  }

  console.error("유효하지 않은 노력치 포맷입니다:", evs);
  return { hp: 0, atk: 0, def: 0, catk: 0, cdef: 0, speed: 0 };
}

class PokemonTemplate {
  // prettier-ignore
  constructor(id, pokemon_id, gacha, evs, up, down, sk1, sk2, sk3, sk4, item, abil, role, tip = ""){
    const parsedEvs = parseEvs(evs);
    const { hp: hps, atk: atks, def: defs, catk: catks, cdef: cdefs, speed: speeds } = parsedEvs;
    this._validateParams(id, pokemon_id, gacha, hps, atks, defs, catks, cdefs, speeds, up, down, sk1, sk2, sk3, sk4, item, abil, role, tip);
    this.evsInput = evs;
    this.role = role;
    this.tip = tip;

    this.id = id;
    pokemonList.push(id)
    this.skill = {
      1: { ...skillList.search(sk1), skillNumber: 1 },
      2: { ...skillList.search(sk2), skillNumber: 2 },
      3: { ...skillList.search(sk3), skillNumber: 3 },
      4: { ...skillList.search(sk4), skillNumber: 4 },
    };
    this.item = item;
    this.itemText = itemText[item];
    this.abil = abil;
    this.abilObj = abilObject[abil] ? abilObject[abil] : {}
    this.abilObj.name = abil

    const pokemon = PokemonData.getDataById(pokemon_id);
    this.no = pokemon.no;
    this.pokemon_id = pokemon.id; //ex) 0815
    this.name = pokemon.name;
    this.names = pokemon.names;
    this.namess = pokemon.namess;
    this.type1 = pokemon.type1;
    this.type2 = pokemon.type2;
    this.feature = pokemon.feature;
    this.abilList = pokemon.abilList || [abil];
    this.gacha = gacha;
    this.evs = { hp: hps, atk: atks, def: defs, catk: catks, cdef: cdefs, speed: speeds };
    this.nature = { up, down };

    this.stat = {
      atk: null,
      def: null,
      catk: null,
      cdef: null,
      speed: null,
    }
    this.hp = pokemon.hp * 2 + Math.floor(hps / 4);
    this.stat.atk = pokemon.atk * 2 + Math.floor(atks / 4);
    this.stat.def = pokemon.def * 2 + Math.floor(defs / 4);
    this.stat.catk = pokemon.catk * 2 + Math.floor(catks / 4);
    this.stat.cdef = pokemon.cdef * 2 + Math.floor(cdefs / 4);
    this.stat.speed = pokemon.speed * 2 + Math.floor(speeds / 4);

    const gachaStats = {
      "6V": ["hp", "atk", "def", "catk", "cdef", "speed"],
      "5V0S": ["hp", "atk", "def", "catk", "cdef"], // 스피드 제외
      "5V0A": ["hp", "def", "catk", "cdef", "speed"], // 공격 제외
      "4V0A0S": ["hp", "def", "catk", "cdef"], // 공격 스피드 제외
    };

    if (gachaStats[gacha]) {
      gachaStats[gacha].forEach((stat) => {
        if(stat === "hp"){
          this[stat]+=31
        }
        else{
          this.stat[stat] += 31;
        }
      });

    } else {
      console.error(this.id + " 개체치부여안됨");
    }

    this.hp = Math.floor(this.hp / 2) + 60;
    this.stat.atk = Math.floor(this.stat.atk / 2) + 5;
    this.stat.def = Math.floor(this.stat.def / 2) + 5;
    this.stat.catk = Math.floor(this.stat.catk / 2) + 5;
    this.stat.cdef = Math.floor(this.stat.cdef / 2) + 5;
    this.stat.speed = Math.floor(this.stat.speed / 2) + 5;


    let updowntrigger = 0;
    if (up === "hp" || down === "hp") {
      console.error("성격체력오류");
    }
    if (this.stat[up]) {
      this.stat[up] = Math.floor(this.stat[up] * 1.1);
      updowntrigger += 1;
    }

    if (this.stat[down]) {
      this.stat[down] = Math.floor(this.stat[down] * 0.9);
      updowntrigger += 1;
    }

    if (updowntrigger !== 2) {
      console.error(this.id + " 성격처리오류");
    }

    const targetMega = getMegaData(this.pokemon_id, this.item);
    if (targetMega) {
      const megaPokemon = PokemonData.getDataById(targetMega.megaFormId);
      if (megaPokemon) {
        let mAtk = Math.floor((megaPokemon.atk * 2 + Math.floor(atks / 4) + (gachaStats[gacha]?.includes("atk") ? 31 : 0)) / 2) + 5;
        let mDef = Math.floor((megaPokemon.def * 2 + Math.floor(defs / 4) + (gachaStats[gacha]?.includes("def") ? 31 : 0)) / 2) + 5;
        let mCatk = Math.floor((megaPokemon.catk * 2 + Math.floor(catks / 4) + (gachaStats[gacha]?.includes("catk") ? 31 : 0)) / 2) + 5;
        let mCdef = Math.floor((megaPokemon.cdef * 2 + Math.floor(cdefs / 4) + (gachaStats[gacha]?.includes("cdef") ? 31 : 0)) / 2) + 5;
        let mSpeed = Math.floor((megaPokemon.speed * 2 + Math.floor(speeds / 4) + (gachaStats[gacha]?.includes("speed") ? 31 : 0)) / 2) + 5;

        const mStat = { atk: mAtk, def: mDef, catk: mCatk, cdef: mCdef, speed: mSpeed };
        if (mStat[up]) mStat[up] = Math.floor(mStat[up] * 1.1);
        if (mStat[down]) mStat[down] = Math.floor(mStat[down] * 0.9);

        this.megaData = {
          name: megaPokemon.name,
          pokemon_id: megaPokemon.id,
          type1: megaPokemon.type1,
          type2: megaPokemon.type2,
          abil: targetMega.abil,
          stone: targetMega.stone,
          stat: mStat,
        };
      }
    }
  }
  // prettier-ignore
  _validateParams(id, pokemon_id, gacha, hps, atks, defs, catks, cdefs, speeds, up, down, sk1, sk2, sk3, sk4, item, abil, role, tip){
    if (!["물리막이", "특수막이", "물리어태커", "특수어태커", "기점잡이", "물리딜탱", "특수딜탱", "막이"].includes(role)) console.error("role must be one of 물리막이, 특수막이, 물리어태커, 특수어태커, 기점잡이, 물리딜탱, 특수딜탱, 막이", role);
    if (typeof id !== "string") console.error("id must be a string", id);
    if (typeof pokemon_id !== "string")
      console.error("pokemon_id must be a string", pokemon_id);
    if (!["6V", "5V0A", "5V0S", "4V0A0S"].includes(gacha))
      console.error("gacha must be one of '6V', '5V0A', '5V0S', '4V0A0S'", gacha);
    if (typeof hps !== "number") console.error("hps must be a number", hps);
    if (typeof atks !== "number") console.error("atks must be a number", atks);
    if (typeof defs !== "number") console.error("defs must be a number", defs);
    if (typeof catks !== "number")
      console.error("catks must be a number", catks);
    if (typeof cdefs !== "number")
      console.error("cdefs must be a number", cdefs);
    if (typeof speeds !== "number")
      console.error("speeds must be a number", speeds);
    if (hps + atks + catks + defs + cdefs + speeds !== 508) {
      console.error(id + "노력치 오류");
            console.error(hps + atks + catks + defs + cdefs + speeds );
    }
    if (!["atk", "def", "catk", "cdef", "speed"].includes(up))
      console.error(
        "up must be one of 'atk', 'def', 'catk', 'cdef', 'speed'",
        up
      );
    if (!["atk", "def", "catk", "cdef", "speed"].includes(down))
      console.error(
        "down must be one of 'atk', 'def', 'catk', 'cdef', 'speed'",
        down
      );
    if (typeof sk1 !== "string") console.error("sk1 must be a string", sk1);
    if (typeof sk2 !== "string") console.error("sk2 must be a string", sk2);
    if (typeof sk3 !== "string") console.error("sk3 must be a string", sk3);
    if (typeof sk4 !== "string") console.error("sk4 must be a string", sk4);
    if (typeof skillList.search(sk1) !== "object")
      console.error("sk1 skill not exist", skillList.search(sk1));
    if (typeof skillList.search(sk2) !== "object")
      console.error("sk2 skill not exist", skillList.search(sk2));
    if (typeof skillList.search(sk3) !== "object")
      console.error("sk3 skill not exist", skillList.search(sk3));
    if (typeof skillList.search(sk4) !== "object")
      console.error("sk4 skill not exist", skillList.search(sk4));

    if (typeof item !== "string") console.error("item must be a string", item);
    if (typeof abil !== "string") console.error("abil must be a string", abil);
    if (abilObject[abil] === null || abilObject[abil] === undefined)
      console.error("abilText not found", abil);
    if (itemText[item] === null || itemText[item] === undefined)
      console.error("itemText not found", item);
  }
}

export const pokemonList = [];
export const POKEMON_ROLES = ["물리어태커", "특수어태커", "기점잡이", "물리딜탱", "특수딜탱", "막이", "물리막이", "특수막이"];

export default PokemonTemplate;
